<script>document.addEventListener('DOMContentLoaded',()=>{const modalElement=document.querySelector('#inventoryAdjustModal'),modal=bootstrap.Modal.getOrCreateInstance(modalElement),form=modalElement.querySelector('[data-adjust-form]'),name=modalElement.querySelector('[data-adjust-name]'),current=modalElement.querySelector('[data-adjust-current]'),message=modalElement.querySelector('[data-adjust-message]'),quantity=form.elements.quantity,minimum=form.elements.minimum_stock;let url='',sign=1;document.querySelectorAll('[data-adjust-button]').forEach(button=>button.addEventListener('click',()=>{url=button.dataset.url;name.textContent=button.dataset.name;current.textContent=button.dataset.stock+' piezas';minimum.value=button.dataset.minimum;quantity.value='';form.elements.note.value='';message.className='alert d-none mt-3 mb-0';sign=1;modalElement.querySelectorAll('[data-sign]').forEach(item=>item.classList.toggle('active',item.dataset.sign==='in'));modal.show()}));modalElement.querySelectorAll('[data-sign]').forEach(button=>button.addEventListener('click',()=>{sign=button.dataset.sign==='in'?1:-1;modalElement.querySelectorAll('[data-sign]').forEach(item=>item.classList.toggle('active',item===button))}));form.addEventListener('submit',async event=>{event.preventDefault();const submit=form.querySelector('[type=submit]');submit.disabled=true;try{const response=await fetch(url,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({quantity:sign*Math.abs(Number(quantity.value)),note:form.elements.note.value,minimum_stock:Number(minimum.value)})}),payload=await response.json();if(!response.ok)throw new Error(payload.message||Object.values(payload.errors||{}).flat()[0]);await Swal.fire({title:'Inventario actualizado',text:payload.message,icon:'success',confirmButtonText:'Listo'});location.reload()}catch(error){message.className='alert alert-danger mt-3 mb-0';message.textContent=error.message}finally{submit.disabled=false}})});</script>@endcan
<script>document.addEventListener('DOMContentLoaded',()=>document.querySelectorAll('[data-inventory-product]').forEach(card=>{const stock=Number(card.querySelector('[data-stock]')?.textContent||0);if(stock<0){const level=card.querySelector('.inventory-level'),unit=card.querySelector('.inventory-count span');level.textContent=`Faltan ${Math.abs(stock)}`;level.className='inventory-level is-out';if(unit)unit.textContent='por surtir'}}))</script>
